@_documentation(visibility: private)
#endif
public struct FfiConverterTypeDdbError: FfiConverterRustBuffer {
    typealias SwiftType = DdbError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DdbError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Git(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Yaml(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 3: return .Sql(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 4: return .Automerge(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 5: return .Io(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 6: return .Parse(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 7: return .NotFound(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 8: return .Config(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 9: return .Validation(
            msg: try FfiConverterString.read(from: &buf), 
            code: try FfiConverterOptionString.read(from: &buf), 
            context: try FfiConverterSequenceTypeDdbErrorContextEntry.read(from: &buf)
            )
        case 10: return .SqlEngine(
            msg: try FfiConverterString.read(from: &buf), 
            code: try FfiConverterOptionString.read(from: &buf), 
            context: try FfiConverterSequenceTypeDdbErrorContextEntry.read(from: &buf)
            )
        case 11: return .Conflict(
            msg: try FfiConverterString.read(from: &buf), 
            code: try FfiConverterOptionString.read(from: &buf), 
            context: try FfiConverterSequenceTypeDdbErrorContextEntry.read(from: &buf)
            )
        case 12: return .VersionMismatch(
            msg: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DdbError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Git(msg):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Yaml(msg):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Sql(msg):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Automerge(msg):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Io(msg):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Parse(msg):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .NotFound(msg):
            writeInt(&buf, Int32(7))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Config(msg):
            writeInt(&buf, Int32(8))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .Validation(msg,code,context):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(msg, into: &buf)
            FfiConverterOptionString.write(code, into: &buf)
            FfiConverterSequenceTypeDdbErrorContextEntry.write(context, into: &buf)
            
        
        case let .SqlEngine(msg,code,context):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(msg, into: &buf)
            FfiConverterOptionString.write(code, into: &buf)
            FfiConverterSequenceTypeDdbErrorContextEntry.write(context, into: &buf)
            
        
        case let .Conflict(msg,code,context):
            writeInt(&buf, Int32(11))
            FfiConverterString.write(msg, into: &buf)
            FfiConverterOptionString.write(code, into: &buf)
            FfiConverterSequenceTypeDdbErrorContextEntry.write(context, into: &buf)
            
        
        case let .VersionMismatch(msg):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(msg, into: &buf)
            
        }
    }
}


